import zipfile, xml.etree.ElementTree as ET, re

path = 'sales_data_new.xlsx'
z = zipfile.ZipFile(path)
# Validate zip integrity
bad = z.testzip()
assert bad is None, f'corrupt member: {bad}'
print('zip OK; members:', z.namelist())

ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

# Well-formedness of modified parts
for part in ('xl/worksheets/sheet1.xml', 'xl/styles.xml'):
    ET.fromstring(z.read(part))
    print(f'{part}: well-formed XML')

# Simulate full evaluation: C, D, F are inputs; E=C*D; G=E-C*F; H=G/E
sheet = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
cells = {}
for c in sheet.iter('{%s}c' % ns['m']):
    ref = c.get('r')
    f = c.find('m:f', ns)
    v = c.find('m:v', ns)
    cells[ref] = {'f': f.text if f is not None else None,
                  'v': float(v.text) if v is not None and v.text not in (None, '') else None}

def col(ref): return re.match(r'([A-Z]+)', ref).group(1)
def row(ref): return int(re.search(r'(\d+)$', ref).group(1))

# inputs
vals = {ref: c['v'] for ref, c in cells.items() if c['f'] is None and c['v'] is not None}
def calc(ref):
    c = cells[ref]
    if c['f'] is None:
        return vals.get(ref)
    f = c['f'].replace('SUM(', 'sum(')
    # build namespace of referenced cells (recursively resolved)
    refs = re.findall(r'[A-Z]{1,2}\d+', f)
    loc = {}
    for r in refs:
        v = calc(r)
        assert v is not None, f'{ref}: unresolved ref {r}'
        loc[r] = v
    expr = re.sub(r'[A-Z]{1,2}\d+', lambda m: repr(loc[m.group(0)]), f)
    return eval(expr)

errors = 0
for ref, c in sorted(cells.items(), key=lambda kv: (row(kv[0]), col(kv[0]))):
    if c['f']:
        try:
            val = calc(ref)
            print(f'{ref}: {c["f"]} = {val:.4f}')
        except Exception as e:
            errors += 1
            print(f'{ref}: ERROR {e}')

print('\nFormula errors:', errors)
assert errors == 0
assert abs(calc('H10') - 23930/45815) < 1e-9, 'H10 margin mismatch'
print('H2 margin expected 0.400 ->', round(calc('H2'), 4))
print('All formulas evaluate without errors. Validation passed.')
