import zipfile, xml.etree.ElementTree as ET, re

z = zipfile.ZipFile('sales_data_new.xlsx')
ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
sheet = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
cells = {}
for c in sheet.iter('{%s}c' % ns['m']):
    f = c.find('m:f', ns); v = c.find('m:v', ns)
    cells[c.get('r')] = {'f': f.text if f is not None else None,
                         'v': float(v.text) if v is not None and v.text not in (None, '') else None}

def row(r): return int(re.search(r'\d+$', r).group(0))
def col(r): return re.match(r'[A-Z]+', r).group(0)
COLS = 'ABCDEFGH'
def expand_range(rng):
    a, b = rng.split(':')
    out = []
    for rr in range(row(a), row(b)+1):
        for cc in range(COLS.index(col(a)), COLS.index(col(b))+1):
            out.append(f'{COLS[cc]}{rr}')
    return out

def calc(ref):
    c = cells[ref]
    if c['f'] is None:
        return c['v']
    f = c['f']
    f = re.sub(r'SUM\(([A-Z]+\d+:[A-Z]+\d+)\)', lambda m: 'sum([' + ','.join(expand_range(m.group(1))) + '])', f)
    refs = re.findall(r'\b[A-Z]{1,2}\d+\b', f)
    loc = {}
    for r in refs:
        v = calc(r)
        assert v is not None, f'{ref}: unresolved {r}'
        loc[r] = v
    expr = re.sub(r'\b[A-Z]{1,2}\d+\b', lambda m: repr(loc[m.group(0)]), f)
    return eval(expr)

errors = 0
for ref, c in sorted(cells.items(), key=lambda kv: (row(kv[0]), col(kv[0]))):
    if c['f']:
        val = calc(ref)
        print(f'{ref}: {c["f"]} = {val:.4f}')
print('\nFormula errors:', errors)
assert abs(calc('H10') - 23930/45815) < 1e-9
print('H10 (total margin) = %.4f  (expected 0.5223)' % calc('H10'))
print('ALL FORMULAS EVALUATE CLEANLY - validation passed')
PYEOF
